reactiveclass Counter {
	knownrebecs {
		Client counterClient1;
		Client counterClient2;
	}

	statevars {
		int count;
		Client clientRef;
	}

	msgsrv initial() {
		count = 0;
	}

	msgsrv Increment(Client sender) {
		count = count + 1;
		clientRef = sender;
		clientRef.ValueResponse(count);
	}

	msgsrv Decrement(Client sender) {
		count = count - 1;
		clientRef = sender;
		clientRef.ValueResponse(count);
	}

	msgsrv GetValue(Client sender) {
		clientRef = sender;
		clientRef.ValueResponse(count);
	}
}

